-- 000001: initial schema (SQLite dialect; IDs are UUID strings generated by the app)
-- roles, users, modules/permissions/role_modules,
-- campuses -> stories -> classes, subjects -> lectures/seminars/quizzes/flashcards,
-- student consumption (enrollments, quiz attempts)

/* ---------- roles & users ---------- */

CREATE TABLE roles (
  id   TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  name          TEXT NOT NULL,
  role_id       TEXT NOT NULL REFERENCES roles(id),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

/* ---------- modules & permissions ---------- */

CREATE TABLE modules (
  id          TEXT PRIMARY KEY,
  key         TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  description TEXT
);

CREATE TABLE permissions (
  id        TEXT PRIMARY KEY,
  module_id TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE,
  action    TEXT NOT NULL, -- create | read | update | delete
  UNIQUE (module_id, action)
);

-- a role having a module means access to everything inside that module
CREATE TABLE role_modules (
  role_id   TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  module_id TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, module_id)
);

/* ---------- school structure: campuses -> stories -> classes ---------- */

CREATE TABLE campuses (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  address    TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE stories (
  id           TEXT PRIMARY KEY,
  campus_id    TEXT NOT NULL REFERENCES campuses(id) ON DELETE CASCADE,
  floor_number INTEGER NOT NULL,
  name         TEXT,
  UNIQUE (campus_id, floor_number)
);

CREATE TABLE classes (
  id         TEXT PRIMARY KEY,
  story_id   TEXT NOT NULL REFERENCES stories(id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  capacity   INTEGER NOT NULL DEFAULT 30,
  tags       TEXT NOT NULL DEFAULT '[]', -- JSON array, e.g. ["computers","lab"]
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

/* ---------- academic content ---------- */

CREATE TABLE subjects (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  code        TEXT UNIQUE,
  description TEXT,
  lecturer_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE lectures (
  id           TEXT PRIMARY KEY,
  subject_id   TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  class_id     TEXT REFERENCES classes(id) ON DELETE SET NULL, -- room
  title        TEXT NOT NULL,
  description  TEXT,
  scheduled_at TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE TABLE seminars (
  id           TEXT PRIMARY KEY,
  subject_id   TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  class_id     TEXT REFERENCES classes(id) ON DELETE SET NULL, -- room
  title        TEXT NOT NULL,
  description  TEXT,
  scheduled_at TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE TABLE quizzes (
  id                 TEXT PRIMARY KEY,
  subject_id         TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  title              TEXT NOT NULL,
  description        TEXT,
  time_limit_minutes INTEGER,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);

CREATE TABLE quiz_questions (
  id          TEXT PRIMARY KEY,
  quiz_id     TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
  type        TEXT NOT NULL, -- mcq | true_false | short_answer
  prompt      TEXT NOT NULL,
  options     TEXT NOT NULL DEFAULT '[]', -- JSON array of strings
  answer      TEXT NOT NULL,              -- JSON value
  points      INTEGER NOT NULL DEFAULT 1,
  order_index INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE flashcards (
  id         TEXT PRIMARY KEY,
  subject_id TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  front      TEXT NOT NULL,
  back       TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

/* ---------- students consume content ---------- */

CREATE TABLE enrollments (
  id          TEXT PRIMARY KEY,
  student_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  subject_id  TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
  enrolled_at TEXT NOT NULL,
  UNIQUE (student_id, subject_id)
);

CREATE TABLE quiz_attempts (
  id           TEXT PRIMARY KEY,
  quiz_id      TEXT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
  student_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  score        INTEGER NOT NULL DEFAULT 0,
  completed_at TEXT NOT NULL
);
